import 'dart:io' show Platform;

import 'package:flutter/foundation.dart';
import 'package:games_services/games_services.dart';

/// Game Center / Play Games achievement IDs for every catalog key.
///
/// iOS IDs follow the `cc_<key>` convention configured in App Store Connect.
/// Android IDs are generated by the Play Console — fill them in once Play
/// Games Services is set up; empty means "not configured yet" and unlock
/// skips it.
const Map<String, ({String ios, String android})> platformAchievementIds = {
  'FIRST_GAME': (ios: 'cc_first_game', android: ''),
  'FIRST_WIN': (ios: 'cc_first_win', android: ''),
  'WINS_10': (ios: 'cc_wins_10', android: ''),
  'WINS_50': (ios: 'cc_wins_50', android: ''),
  'WINS_100': (ios: 'cc_wins_100', android: ''),
  'STREAK_5': (ios: 'cc_streak_5', android: ''),
  'STREAK_10': (ios: 'cc_streak_10', android: ''),
  'BEAT_AI_MEDIUM': (ios: 'cc_beat_ai_medium', android: ''),
  'BEAT_AI_HARD': (ios: 'cc_beat_ai_hard', android: ''),
  'SKUNK': (ios: 'cc_skunk', android: ''),
  'DOUBLE_SKUNK': (ios: 'cc_double_skunk', android: ''),
  'SKUNK_AI_HARD': (ios: 'cc_skunk_ai_hard', android: ''),
  'COMEBACK': (ios: 'cc_comeback', android: ''),
  'HAND_20': (ios: 'cc_hand_20', android: ''),
  'HAND_24': (ios: 'cc_hand_24', android: ''),
  'HAND_29': (ios: 'cc_hand_29', android: ''),
  'CRIB_12': (ios: 'cc_crib_12', android: ''),
  'HIS_HEELS': (ios: 'cc_his_heels', android: ''),
  'PEG_31': (ios: 'cc_peg_31', android: ''),
  'PEG_12_ROUND': (ios: 'cc_peg_12_round', android: ''),
  'FIRST_ONLINE_WIN': (ios: 'cc_first_online_win', android: ''),
  'RATING_1600': (ios: 'cc_rating_1600', android: ''),
  'FRIEND_ADDED': (ios: 'cc_friend_added', android: ''),
  'PUZZLE_FIRST': (ios: 'cc_puzzle_first', android: ''),
  'PUZZLE_OPTIMAL_10': (ios: 'cc_puzzle_optimal_10', android: ''),
};

/// Mirrors server-authoritative unlocks to Game Center / Play Games.
///
/// Everything is best-effort: a signed-out platform account or missing
/// console configuration just means no mirroring — the in-app achievements
/// (which are the source of truth) are unaffected. All achievements are
/// configured standard/binary on both platforms, so re-unlocking is
/// idempotent and re-pushing the full earned set is a reconciliation.
class PlatformAchievements {
  bool _signedIn = false;

  bool get _supported => !kIsWeb && (Platform.isIOS || Platform.isAndroid);

  Future<void> signIn() async {
    if (!_supported || _signedIn) return;
    try {
      await GameAuth.signIn();
      _signedIn = await GameAuth.isSignedIn;
    } catch (e) {
      debugPrint('Platform games sign-in unavailable: $e');
      _signedIn = false;
    }
  }

  Future<void> unlockAll(Iterable<String> keys) async {
    if (!_supported) return;
    if (!_signedIn) await signIn();
    if (!_signedIn) return;

    for (final key in keys) {
      final ids = platformAchievementIds[key];
      if (ids == null) continue;
      final platformId = Platform.isIOS ? ids.ios : ids.android;
      if (platformId.isEmpty) continue;
      try {
        await Achievements.unlock(
          achievement: Achievement(
            androidID: ids.android,
            iOSID: ids.ios,
            percentComplete: 100,
          ),
        );
      } catch (e) {
        debugPrint('Failed to unlock $key on platform: $e');
      }
    }
  }
}
